import os
import torch


class Config:
    # ==========================================
    # Path Configuration
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_4"
    SUBMISSION_DIR = "./submission"

    # Input Files
    TRAIN_BSON = os.path.join(INPUT_DIR, "train.bson")
    TEST_BSON = os.path.join(INPUT_DIR, "test.bson")
    CATEGORY_NAMES = os.path.join(INPUT_DIR, "category_names.csv")
    SAMPLE_SUBMISSION = os.path.join(INPUT_DIR, "sample_submission.csv")

    # Metadata Files (Generated by previous steps)
    TRAIN_META = os.path.join(METADATA_DIR, "train.csv")
    VAL_META = os.path.join(METADATA_DIR, "val.csv")
    TEST_META = os.path.join(METADATA_DIR, "test.csv")

    # ==========================================
    # Model Configuration
    # ==========================================
    MODEL_NAME = "convnext_tiny"
    NUM_CLASSES = 5270
    PRETRAINED = True
    IMG_SIZE = 180  # Native size of the dataset
    DROP_PATH_RATE = 0.1

    # ==========================================
    # Training Configuration
    # ==========================================
    SEED = 42
    BATCH_SIZE = 512  # Increased for throughput on A100
    NUM_EPOCHS = 5  # Sufficient for convergence on 12M images

    # Optimization
    LEARNING_RATE = 1e-3  # Max LR for OneCycle
    WEIGHT_DECAY = 0.05
    LABEL_SMOOTHING = 0.1

    # Scheduler (OneCycleLR)
    PCT_START = 0.1
    DIV_FACTOR = 25.0
    FINAL_DIV_FACTOR = 100.0

    # Hardware
    NUM_WORKERS = 12
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    USE_AMP = True  # Automatic Mixed Precision

    # ==========================================
    # Debug / Development
    # ==========================================
    DEBUG = False
    DEBUG_SUBSET_SIZE = 50000  # Number of samples to use in debug mode

    @classmethod
    def setup(cls):
        """Creates necessary output directories."""
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

    @classmethod
    def update(cls, debug=None, epochs=None, batch_size=None):
        """
        Updates configuration based on runtime arguments.
        """
        if debug is not None:
            cls.DEBUG = debug
        if epochs is not None:
            cls.NUM_EPOCHS = epochs
        if batch_size is not None:
            cls.BATCH_SIZE = batch_size
